from datetime import datetime
from typing import Any


_FORMAT = "%Y-%m-%d %H:%M"


def _timestamp(record: dict[str, Any]) -> datetime:
    try:
        value = record["timestamp"]
    except KeyError:
        raise ValueError("missing timestamp") from None
    if not isinstance(value, str):
        raise TypeError("timestamp must be a string")
    try:
        parsed = datetime.strptime(value, _FORMAT)
    except ValueError:
        raise ValueError("invalid timestamp") from None
    if parsed.strftime(_FORMAT) != value:
        raise ValueError("invalid timestamp")
    return parsed


def summarize_activity(
    checkins: list[dict[str, Any]], repairs: list[dict[str, Any]]
) -> tuple[str | None, str | None]:
    if not isinstance(checkins, list) or not isinstance(repairs, list):
        raise TypeError("arguments must be lists")

    parsed_checkins = []
    for index, record in enumerate(checkins):
        if not isinstance(record, dict):
            raise TypeError("records must be dictionaries")
        if "asset" not in record or "location" not in record:
            raise ValueError("missing field")
        if not isinstance(record["asset"], str) or not isinstance(record["location"], str):
            raise TypeError("asset and location must be strings")
        parsed_checkins.append((_timestamp(record), index, record))

    parsed_repairs = []
    for index, record in enumerate(repairs):
        if not isinstance(record, dict):
            raise TypeError("records must be dictionaries")
        if "asset" not in record or "location" not in record or "minutes" not in record:
            raise ValueError("missing field")
        if not isinstance(record["asset"], str) or not isinstance(record["location"], str):
            raise TypeError("asset and location must be strings")
        if isinstance(record["minutes"], bool) or not isinstance(record["minutes"], int):
            raise TypeError("minutes must be an integer")
        if record["minutes"] < 0:
            raise ValueError("minutes must be nonnegative")
        parsed_repairs.append((_timestamp(record), index, record))

    first = None
    if parsed_checkins:
        record = parsed_checkins[0][2]
        first = f"Asset {record['asset']} checked in at {record['location']} on {record['timestamp']}"

    last = None
    if parsed_repairs:
        record = parsed_repairs[-1][2]
        last = f"Asset {record['asset']} repaired at {record['location']} on {record['timestamp']} for {record['minutes']} minutes"

    return first, last

